// Bad: component doing everything
@Component({...})
class OrderComponent {
  orders = [];
  addOrder(item) {
    // HTTP call here – messy!
    this.http.post('/api/orders', item).subscribe(...);
  }
}

// Good: delegate to a service
constructor(private orderService: OrderService) {}

addOrder(item) {
  this.orderService.placeOrder(item);
}
